// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.vision.documentimport timber.log.Timberimport android.content.Contextimport com.roshan.persona.vision.barcode.RegionalQrFormatimport java.io.Fileimport java.security.MessageDigest/** * NOUS — Regional Vision Pack Loader (Module 6 v4 — Step 6.5). * * Loads Regional Vision Packs (RVP) via Play Asset Delivery, per strategy v4 * §"Regional Vision Packs". * * ## Packs (per strategy v4) * * | Pack | OCR Scripts | QR Formats | Currency | Document Types | Size | * |------|------------|-----------|----------|----------------|------| * | India (default) | Devanagari + Latin | UPI, BharatQR | ₹ (INR) | Aadhaar, PAN, GST, Prescription | 280 MB | * | LATAM (opt-in) | Spanish, Portuguese | Pix, Boleto, Mercado Pago | $ (MXN, BRL, ARS) | CPF, CURP, RFC | 240 MB | * | SEA (opt-in) | Thai, Vietnamese, Bahasa | PromptPay, DuitNow, GoPay | ฿, ₫, Rp | Thai ID, KTP, MyKad | 260 MB | * * ## How it works * *  1. User selects a region in Settings → Region → LATAM *  2. [RegionalVisionPackLoader] checks if the LATAM pack is on disk *  3. If not, downloads via Play Asset Delivery (240 MB) *  4. Verifies SHA-256 + Ed25519 signature *  5. Activates the pack (configures OCR + UPI handler + currency formatter) *  6. India pack moves to LRU cache (kept for 7 days, then evicted) * * ## Privacy * *  - Region selection is local (no telemetry). *  - Pack download is one-time (cached on disk). *  - User can switch packs freely (no re-download if previously downloaded). *  - No cloud vision API calls regardless of region. * * @see <a href="docs/strategy/module-6-vision-strategy-v4.md">§Upgrade 5: Regional Vision Packs</a> */class RegionalVisionPackLoader(    private val context: Context,    private val downloader: PackDownloader,    private val verifier: PackVerifier,) {    /** Root directory for vision packs. */    private val packsDir: File = File(context.filesDir, "vision_packs").apply { if (!exists()) mkdirs() }    /** Currently active region (defaults to INDIA). */    @Volatile    private var activeRegion: RegionalQrFormat = RegionalQrFormat.INDIA    /** Cached pack metadata (region → metadata). */    private val packCache = mutableMapOf<RegionalQrFormat, VisionPackMetadata>()    init {        // Load cached metadata for any packs already on disk.        for (region in RegionalQrFormat.entries) {            val metaFile = File(packsDir, "${region.name.lowercase()}.meta.json")            if (metaFile.exists()) {                try {                    val meta = parseMetadata(metaFile.readText())                    if (meta != null) {                        packCache[region] = meta                        Timber.tag(TAG).d("Loaded cached pack metadata for $region.")                    }                } catch (t: Throwable) {                    Timber.tag(TAG).w("Failed to load metadata for $region.", t)                }            }        }    }    /**     * Get the currently active region.     */    fun getActiveRegion(): RegionalQrFormat = activeRegion    /**     * Get metadata for a pack (if cached on disk).     *     * @param region the region to check.     * @return the pack metadata, or null if not downloaded.     */    fun getPackMetadata(region: RegionalQrFormat): VisionPackMetadata? = packCache[region]    /**     * Check if a pack is downloaded + verified on disk.     */    fun isPackDownloaded(region: RegionalQrFormat): Boolean {        val meta = packCache[region] ?: return false        val packFile = File(packsDir, meta.fileName)        return packFile.exists() && verifier.verify(packFile, meta.sha256, meta.signature)    }    /**     * Download a regional vision pack.     *     * @param region the region to download.     * @return the [PackDownloadResult] — SUCCESS, ALREADY_DOWNLOADED, or FAILED.     */    suspend fun downloadPack(region: RegionalQrFormat): PackDownloadResult {        Timber.tag(TAG).i("Downloading vision pack: $region.")        // 1. Check if already downloaded.        if (isPackDownloaded(region)) {            Timber.tag(TAG).d("Pack $region already downloaded.")            return PackDownloadResult.ALREADY_DOWNLOADED(region)        }        // 2. Download via Play Asset Delivery (or fallback to direct download).        val packFileName = "${region.name.lowercase()}_pack.zip"        val targetFile = File(packsDir, packFileName)        val downloadResult = try {            downloader.download(region, targetFile)        } catch (t: Throwable) {            Timber.tag(TAG).e("Pack download failed for $region.", t)            return PackDownloadResult.FAILED(region, "Download failed: ${t.message}")        }        if (!downloadResult.success) {            return PackDownloadResult.FAILED(region, downloadResult.errorMessage ?: "Unknown download error")        }        // 3. Verify SHA-256 + Ed25519 signature.        if (!verifier.verify(targetFile, downloadResult.sha256, downloadResult.signature)) {            Timber.tag(TAG).e("Pack verification failed for $region — deleting.")            targetFile.delete()            return PackDownloadResult.FAILED(region, "Signature verification failed")        }        // 4. Save metadata.        val metadata = VisionPackMetadata(            region = region,            fileName = packFileName,            version = downloadResult.version,            sizeBytes = downloadResult.sizeBytes,            sha256 = downloadResult.sha256,            signature = downloadResult.signature,            downloadTimestamp = System.currentTimeMillis(),        )        packCache[region] = metadata        saveMetadata(region, metadata)        Timber.tag(TAG).i("Pack $region downloaded + verified (${metadata.sizeBytes} bytes).")        return PackDownloadResult.SUCCESS(region, metadata)    }    /**     * Activate a pack (switch the active region).     *     * @param region the region to activate.     * @return true if activation succeeded.     */    fun activatePack(region: RegionalQrFormat): Boolean {        if (!isPackDownloaded(region) && region != RegionalQrFormat.INDIA) {            Timber.tag(TAG).w("Cannot activate $region — pack not downloaded.")            return false        }        activeRegion = region        Timber.tag(TAG).i("Activated vision pack: $region.")        return true    }    /**     * Delete a pack from disk (frees storage).     */    fun deletePack(region: RegionalQrFormat): Boolean {        val meta = packCache[region] ?: return false        val packFile = File(packsDir, meta.fileName)        val deleted = packFile.delete()        if (deleted) {            packCache.remove(region)            File(packsDir, "${region.name.lowercase()}.meta.json").delete()            Timber.tag(TAG).i("Deleted pack $region.")        }        return deleted    }    /**     * Get total storage used by all vision packs (for Settings UI).     */    fun totalStorageBytes(): Long {        return packCache.values.sumOf { it.sizeBytes }    }    /**     * List all downloaded packs with their metadata.     */    fun listDownloadedPacks(): List<VisionPackMetadata> {        return packCache.values.toList()    }    // ─── Internal helpers ─────────────────────────────────────────────────    private fun saveMetadata(region: RegionalQrFormat, metadata: VisionPackMetadata) {        val metaFile = File(packsDir, "${region.name.lowercase()}.meta.json")        metaFile.writeText(serializeMetadata(metadata))    }    private fun serializeMetadata(meta: VisionPackMetadata): String {        // Simple JSON serialization (no dependency on org.json for testability).        return buildString {            append("{")            append("\"region\":\"${meta.region}\",")            append("\"fileName\":\"${meta.fileName}\",")            append("\"version\":\"${meta.version}\",")            append("\"sizeBytes\":${meta.sizeBytes},")            append("\"sha256\":\"${meta.sha256}\",")            append("\"signature\":\"${meta.signature}\",")            append("\"downloadTimestamp\":${meta.downloadTimestamp}")            append("}")        }    }    private fun parseMetadata(json: String): VisionPackMetadata? {        return try {            val region = Regex("\"region\":\"([A-Z]+)\"").find(json)?.groupValues?.getOrNull(1)                ?.let { RegionalQrFormat.valueOf(it) } ?: return null            val fileName = Regex("\"fileName\":\"([^\"]+)\"").find(json)?.groupValues?.getOrNull(1) ?: return null            val version = Regex("\"version\":\"([^\"]+)\"").find(json)?.groupValues?.getOrNull(1) ?: "1.0"            val sizeBytes = Regex("\"sizeBytes\":(\\d+)").find(json)?.groupValues?.getOrNull(1)?.toLong() ?: 0L            val sha256 = Regex("\"sha256\":\"([^\"]+)\"").find(json)?.groupValues?.getOrNull(1) ?: ""            val signature = Regex("\"signature\":\"([^\"]+)\"").find(json)?.groupValues?.getOrNull(1) ?: ""            val timestamp = Regex("\"downloadTimestamp\":(\\d+)").find(json)?.groupValues?.getOrNull(1)?.toLong() ?: 0L            VisionPackMetadata(region, fileName, version, sizeBytes, sha256, signature, timestamp)        } catch (t: Throwable) {            Timber.tag(TAG).w("Failed to parse pack metadata.", t)            null        }    }    private companion object {        private const val TAG = "RegionalPackLoader"    }}// ──────────────────────────────────────────────────────────────────────────/** Metadata for a downloaded vision pack. */data class VisionPackMetadata(    val region: RegionalQrFormat,    val fileName: String,    val version: String,    val sizeBytes: Long,    val sha256: String,    val signature: String,  // Ed25519 signature (hex)    val downloadTimestamp: Long,) {    /** Size in MB (for display). */    val sizeMb: Float get() = sizeBytes / (1024f * 1024f)    /** Age in days (for cache eviction). */    val ageDays: Int        get() = ((System.currentTimeMillis() - downloadTimestamp) / (24 * 60 * 60 * 1000)).toInt()}/** Result of [RegionalVisionPackLoader.downloadPack]. */sealed interface PackDownloadResult {    data class SUCCESS(        val region: RegionalQrFormat,        val metadata: VisionPackMetadata,    ) : PackDownloadResult    data class ALREADY_DOWNLOADED(val region: RegionalQrFormat) : PackDownloadResult    data class FAILED(val region: RegionalQrFormat, val errorMessage: String) : PackDownloadResult}// ──────────────────────────────────────────────────────────────────────────/** Pack downloader interface — abstracts Play Asset Delivery. */interface PackDownloader {    /** Download a pack to [targetFile]. */    suspend fun download(region: RegionalQrFormat, targetFile: File): DownloadResult}/** Result of [PackDownloader.download]. */data class DownloadResult(    val success: Boolean,    val version: String,    val sizeBytes: Long,    val sha256: String,    val signature: String,    val errorMessage: String? = null,)/** Pack verifier interface — abstracts SHA-256 + Ed25519 signature verification. */interface PackVerifier {    /** Verify [file] matches [expectedSha256] + [expectedSignature]. */    fun verify(file: File, expectedSha256: String, expectedSignature: String): Boolean}// ──────────────────────────────────────────────────────────────────────────
